try {
    const data = msg.payload;
    if (!data.unitId || data.temperature === undefined ||
        data.humidity === undefined || !data.compressorStatus ||
        data.energyConsumption === undefined) {
        node.warn('Invalid data format: ' + JSON.stringify(data));
        return null;
    }
    msg.sensorData = {
        unitId: data.unitId,
        temperature: parseFloat(data.temperature),
        humidity: parseFloat(data.humidity),
        compressorStatus: data.compressorStatus,
        energyConsumption: parseFloat(data.energyConsumption),
        timestamp: data.timestamp || new Date().toISOString()
    };
    msg.unitId = data.unitId;
    msg.topic = data.unitId;
    return msg;
} catch (error) {
    node.error('Parse error: ' + error.message, msg);
    return null;
}

const data = msg.sensorData;
const ts = new Date(data.timestamp).getTime() * 1000000;
msg.payload = `sensor_data,unitId=${data.unitId} temperature=${data.temperature},humidity=${data.humidity},compressorStatus="${data.compressorStatus}",energyConsumption=${data.energyConsumption} ${ts}`;
msg.url = 'http://influxdb:8086/api/v2/write?org=smart_cooling&bucket=cold_storage&precision=ns';
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Token smart-cooling-super-secret-token',
    'Content-Type': 'text/plain; charset=utf-8'
};
return msg;

const data = msg.sensorData;
const unitId = data.unitId;
const tempStatus = data.temperature > 8 ? 'critical' :
                   data.temperature > 6 ? 'warning' : 'normal';
const humidityStatus = (data.humidity > 80 || data.humidity < 50) ? 'warning' : 'normal';
const energyEfficiency = data.energyConsumption > 4 ? 'critical' :
                         data.energyConsumption > 3 ? 'inefficient' : 'normal';
const dittoPayload = {
    features: {
        temperature: { properties: { value: data.temperature, status: tempStatus, lastUpdated: data.timestamp } },
        humidity: { properties: { value: data.humidity, status: humidityStatus, lastUpdated: data.timestamp } },
        compressor: { properties: { status: data.compressorStatus, lastUpdated: data.timestamp } },
        energy: { properties: { consumption: data.energyConsumption, efficiency: energyEfficiency, lastUpdated: data.timestamp } },
        connectivity: { properties: { connected: true, lastSeen: data.timestamp } }
    }
};
msg.payload = dittoPayload;
msg.url = `http://ditto-gateway:8080/api/2/things/org.eclipse.ditto:${unitId}`;
msg.method = 'PATCH';
msg.headers = { 'Content-Type': 'application/merge-patch+json', 'x-ditto-pre-authenticated': 'nginx:nodered' };
return msg;

const data = msg.sensorData;
const alerts = [];
const TEMP_CRITICAL_HIGH = 10.0, TEMP_WARNING_HIGH = 8.0;
const TEMP_WARNING_LOW = 2.0, TEMP_CRITICAL_LOW = 0.0;
const HUMIDITY_HIGH = 80, HUMIDITY_LOW = 50;
const ENERGY_WARNING = 3.0, ENERGY_CRITICAL = 4.0;

if (data.temperature >= TEMP_CRITICAL_HIGH) {
    alerts.push({ unitId: data.unitId, alertType: 'temperature_critical_high', severity: 'critical',
        message: `Temperature critically high: ${data.temperature}°C`, value: data.temperature, threshold: TEMP_CRITICAL_HIGH, timestamp: data.timestamp });
} else if (data.temperature >= TEMP_WARNING_HIGH) {
    alerts.push({ unitId: data.unitId, alertType: 'temperature_warning_high', severity: 'warning',
        message: `Temperature above normal: ${data.temperature}°C`, value: data.temperature, threshold: TEMP_WARNING_HIGH, timestamp: data.timestamp });
} else if (data.temperature <= TEMP_CRITICAL_LOW) {
    alerts.push({ unitId: data.unitId, alertType: 'temperature_critical_low', severity: 'critical',
        message: `Temperature critically low: ${data.temperature}°C`, value: data.temperature, threshold: TEMP_CRITICAL_LOW, timestamp: data.timestamp });
} else if (data.temperature <= TEMP_WARNING_LOW) {
    alerts.push({ unitId: data.unitId, alertType: 'temperature_warning_low', severity: 'warning',
        message: `Temperature below normal: ${data.temperature}°C`, value: data.temperature, threshold: TEMP_WARNING_LOW, timestamp: data.timestamp });
}
if (data.humidity > HUMIDITY_HIGH || data.humidity < HUMIDITY_LOW) {
    alerts.push({ unitId: data.unitId, alertType: 'humidity_out_of_range', severity: 'warning',
        message: `Humidity out of range: ${data.humidity}%`, value: data.humidity,
        threshold: data.humidity > HUMIDITY_HIGH ? HUMIDITY_HIGH : HUMIDITY_LOW, timestamp: data.timestamp });
}
if (data.energyConsumption >= ENERGY_CRITICAL) {
    alerts.push({ unitId: data.unitId, alertType: 'energy_critical', severity: 'critical',
        message: `Energy critically high: ${data.energyConsumption}kW`, value: data.energyConsumption, threshold: ENERGY_CRITICAL, timestamp: data.timestamp });
} else if (data.energyConsumption >= ENERGY_WARNING) {
    alerts.push({ unitId: data.unitId, alertType: 'energy_warning', severity: 'warning',
        message: `Energy elevated: ${data.energyConsumption}kW`, value: data.energyConsumption, threshold: ENERGY_WARNING, timestamp: data.timestamp });
}
if (alerts.length > 0) { msg.alerts = alerts; msg.sensorData = data; return msg; }
return null;

const alerts = msg.alerts || [];
const outputs = [];
for (const alert of alerts) {
    outputs.push({ payload: alert, topic: `coldstorage/${alert.unitId}/alerts` });
}
return [outputs];

const alert = msg.payload;
const ts = new Date(alert.timestamp).getTime() * 1000000;
msg.payload = `alerts,unitId=${alert.unitId},alertType=${alert.alertType},severity=${alert.severity} message="${alert.message}",value=${alert.value},threshold=${alert.threshold},resolved="false" ${ts}`;
msg.url = 'http://influxdb:8086/api/v2/write?org=smart_cooling&bucket=alerts&precision=ns';
msg.method = 'POST';
msg.headers = {
    'Authorization': 'Token smart-cooling-super-secret-token',
    'Content-Type': 'text/plain; charset=utf-8'
};
return msg;

const alert = msg.payload;
const cooldownMs = 10 * 60 * 1000; // 10 minutes
const key = `${alert.unitId}_${alert.alertType}`;
const lastSent = context.get(key) || 0;
const now = Date.now();

if (now - lastSent < cooldownMs) {
    node.debug(`Cooldown active for ${key}, skipping email`);
    return null;
}
context.set(key, now);
return msg;

const alert = msg.payload;
const severityIcon = alert.severity === 'critical' ? '🔴 CRITICAL' : '🟡 WARNING';
const ts = new Date(alert.timestamp).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

msg.topic = `[Smart Cold Storage] ${severityIcon} - ${alert.unitId}: ${alert.alertType.replace(/_/g,' ').toUpperCase()}`;

msg.payload = `Smart Cold Storage Alert
==========================================

Severity  : ${severityIcon}
Unit      : ${alert.unitId}
Alert Type: ${alert.alertType.replace(/_/g,' ')}
Message   : ${alert.message}
Value     : ${alert.value}
Threshold : ${alert.threshold}
Time (IST): ${ts}

==========================================
Action Required:
${alert.severity === 'critical'
  ? 'IMMEDIATE action required. Check the unit and contact maintenance team.'
  : 'Monitor the unit closely. Take corrective action if trend continues.'}

-- Smart Cold Storage Monitoring System`;

return msg;
